// Generated by `cargo xtask schema` from Rust's `stress_lab`; do not edit.

/** A workload as the page polls it, serialized only when it polls. */
export interface StressSnapshot {
  assets: AssetSnapshot;
  camera: CameraSnapshot;
  collision: CollisionSnapshot;
  /** The configuration the workload was built from. */
  config: StressConfig;
  /** The frame and fixed tick, as decimal strings. */
  frame: string;
  /**
   * The workload's generation: one more each time a configuration
   * rebuilds it.
   */
  generation: number;
  interpolation: InterpolationSnapshot;
  moving_nodes: number;
  queries: QuerySnapshot;
  /** Renderable objects, transform nodes, and the moving and sensor ones. */
  renderables: number;
  sensor_nodes: number;
  tick: string;
  timings: TimingSnapshot;
  transform_nodes: number;
  /** The snapshot format's version. */
  version: number;
}

/** The asset library: counts and resident CPU bytes. */
export interface AssetSnapshot {
  cpu_bytes: number;
  materials: number;
  meshes: number;
  texture_bytes: number;
  textures: number;
}

/** The camera: eye, target, vertical field of view and depth range. */
export interface CameraSnapshot {
  far: number;
  near: number;
  position: number[];
  target: number[];
  vertical_fov_radians: number;
}

/** Collision and sensors: counts, completeness and errors. */
export interface CollisionSnapshot {
  active_colliders: number;
  bvh_nodes: number;
  cache_bytes: number;
  colliders: number;
  /** Whether every collider entered the world. */
  complete: boolean;
  /** Whether the workload has collision at all. */
  enabled: boolean;
  /** The collision world's last error code. */
  error: string | null;
  invalid_colliders: number;
  overflow_colliders: number;
  /** The collision world's revision and tick, as decimal strings. */
  revision: string;
  /**
   * The ticks sensor detection last ran and last committed, as decimal
   * strings.
   */
  sensor_attempted_tick: string | null;
  sensor_candidates: number;
  sensor_committed_tick: string | null;
  /** Whether sensor detection covered every candidate pair. */
  sensor_complete: boolean;
  /** Sensor detection's error code. */
  sensor_error: string | null;
  sensor_events: number;
  sensor_pairs: number;
  tick: string;
}

/** Interpolation history and presented poses: nodes and bytes. */
export interface InterpolationSnapshot {
  history_bytes: number;
  history_nodes: number;
  presented_nodes: number;
  presented_store_bytes: number;
  scratch_bytes: number;
}

/**
 * Spatial queries: the last frame's and every frame's, totals as decimal
 * strings.
 */
export interface QuerySnapshot {
  calls: number;
  errors: number;
  hits: number;
  last_error: string | null;
  total_calls: string;
  total_errors: string;
  total_hits: string;
}

/**
 * A deterministic stress workload. Configuration changes rebuild the
 * owned workload outside the frame loop; configurations without `scene`
 * build the tower field. The bounds are sanity bounds for URLs and the
 * page: the engine sets none.
 */
export interface StressConfig {
  /** Colliders, at most one per renderable. */
  colliders: number;
  /**
   * Metro textures as BC7 blocks with their mip chains,
   * for devices with `texture-compression-bc`; RGBA8 otherwise.
   */
  compressed_textures: boolean;
  /** Whether frustum culling runs. */
  culling: boolean;
  /** Whether colliders gather in dense clusters past pair budgets. */
  dense_colliders: boolean;
  /** Whether moving renderables form parent hierarchies. */
  hierarchy: boolean;
  /** Whether moving renderables interpolate between fixed ticks. */
  interpolation: boolean;
  /**
   * Mesh batches the renderables draw from: one of
   * [`MESH_VARIETIES`].
   */
  mesh_variety: number;
  /** Share of the renderables that move, in percent. */
  moving_percent: number;
  /** Ray, overlap and sweep queries each fixed tick. */
  queries_per_tick: number;
  /** Renderable objects. */
  renderables: number;
  /** The world the workload builds. */
  scene: StressScene;
  /** Seed of every random choice the workload makes. */
  seed: number;
  /** Share of the colliders that are sensors, in percent. */
  sensor_percent: number;
  /** Whether materials are textured. */
  textured: boolean;
}

/** The world a workload builds from its configuration. */
export type StressScene = "field" | "city" | "metro" | "dense" | "highlands";

/**
 * CPU subsets of simulation for the last submitted frame, in
 * milliseconds; not additive to simulation.
 */
export interface TimingSnapshot {
  animation_ms: number;
  queries_ms: number;
  /** What the timings cover. */
  scope: string;
  sensor_ms: number;
  sync_post_ms: number;
  sync_pre_ms: number;
}

